// Get raw text from model
const rawText = $json.text;

// Try to extract JSON part from the text
const jsonStart = rawText.indexOf('{');
const jsonEnd = rawText.lastIndexOf('}');

if (jsonStart === -1 || jsonEnd === -1) {
  throw new Error("No JSON found in text output");
}

const jsonString = rawText.slice(jsonStart, jsonEnd + 1);

// Parse JSON
const parsed = JSON.parse(jsonString);

// Return clean JSON
return parsed;

const raw = $json.text;

// Extract JSON safely
const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');

if (start === -1 || end === -1) {
  throw new Error('No JSON found in Content creator output');
}

const parsed = JSON.parse(raw.slice(start, end + 1));

return {
  caption: parsed.final_post.text,
  image_prompt: parsed.final_post.image_prompt
};
